package com.test.yo.config.properties;

import lombok.Data;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Configuration;

import java.util.List;
import java.util.Map;

@Data
@Configuration
@ConfigurationProperties(prefix = "elastic.apm")
public class ApmProperties {
    private String serviceName;
    private String environment;
    private List<String> serverUrls;
    private List<String> applicationPackages;
    private String logLevel;
    private String secretToken;
    private String verifyServerCert;

    public Map<String, String> asMap() {
        return Map.of(
            "service_name", serviceName, 
            "environment", environment, 
            "server_urls", String.join(",", serverUrls), 
            "application_packages", String.join(",", applicationPackages),
            "log_level", logLevel, 
            "secret_token", secretToken, 
            "verify_server_cert", verifyServerCert);
    }
}

package com.test.yo.config;

import co.elastic.apm.attach.ElasticApmAttacher;
import com.test.yo.config.properties.ApmProperties;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

@Component
public class ApmConfig {
    private final ApmProperties apmProperties;

    @Autowired
    public ApmConfig(ApmProperties apmProperties) {
        this.apmProperties = apmProperties;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void initializeApm() {
        ElasticApmAttacher.attach(apmProperties.asMap());
    }
}

