package com.test.yo.config;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.actuate.info.InfoEndpoint;
import org.springframework.boot.actuate.info.MapInfoContributor;
import org.springframework.context.annotation.Bean;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Component
public class BuildInfoConfig {
    @Autowired
    private Environment environment;

    @Bean
    public InfoEndpoint info() {
        final Map<String, Object> props = new LinkedHashMap<>();
        props.put("buildDate", environment.getProperty("BUILD_DATE"));
        props.put("gitCommit", environment.getProperty("GIT_COMMIT"));
        props.put("gitBranch", environment.getProperty("GIT_BRANCH"));
        return new InfoEndpoint(List.of(new MapInfoContributor(props)));
    }
}

